# default to stdout, overridable through -o|--output
output="/dev/stdout"

while true; do
	case "$1" in
	-o | --output)
		output="$2"
		shift
		shift
		;;
	-*)
		echo "unknown argument: $1"
		exit 1
		;;
	*)
		break
		;;
	esac
done

if [[ "$#" -ne 3 ]]; then
	echo "usage: $0 <owner/repo> <head> <base>"
	exit 1
fi

repo="$1"
head="$2"
base="$3"

# header
cat > "$output" <<EOF
# autogenerated file
# generated by nix-from-compare
{
  fetchpatch2,
  fetchurl,
}:
{
  patches = [
EOF

data="$(curl "https://api.github.com/repos/${repo}/compare/${base}...${head}")"

# generate patches from all commits
jq -r '.commits | .[] | .sha' <<<"$data" | \
while read -r sha; do
	url="https://github.com/${repo}/commit/${sha}.patch?full_index=1"
	for _ in {0..2}; do
		hash="$(
			echo "prefetching patch $url" >&2;
			nix build --impure --expr 'let pkgs = import <nixpkgs> {}; in pkgs.fetchpatch2 {
				name = "'"${sha}.patch"'";
				url = "'"${url}"'";
				hash = pkgs.lib.fakeHash;
			}' 2>&1 | grep got: | awk '{ print $2 }' || true
		)"
		if [[ -z "$hash" ]]; then
			echo "waiting before retry..."
			sleep 10
		else
			break
		fi
	done
	cat >> "$output" <<EOF
    (fetchpatch2 {
      name = "$sha.patch";
      url = "$url";
      hash = "$hash";
    })
EOF
	sleep 2
done

echo -e '  ];\n  files = [' >> "$output"

# generate additional files that fetchpatch filters out
jq -c '.files | .[] | select(has("patch") | not) | {name:.filename,url:.raw_url}' <<<"$data" | \
while read -r json; do
	name="$(jq -r '.name' <<<"$json")"
	url="$(jq -r '.url' <<<"$json")"
	hash="$(
		echo "prefetching url $url" >&2;
		nix build --impure --expr 'let pkgs = import <nixpkgs> {}; in pkgs.fetchurl {
			url = "'"${url}"'";
			hash = pkgs.lib.fakeHash;
		}' 2>&1 | grep got: | awk '{ print $2 }' || true
	)"
	cat >> "$output" <<EOF
    {
      src = fetchurl {
        url = "$url";
        hash = "$hash";
      };
      name = "$name";
    }
EOF
	sleep 2
done

echo -e '  ];\n}' >> "$output"
